private lemma other_positive (a b : B) (q : k) (hq : q ≠ 0)
    (hs : qSerre q 3 b a = 0) (ht : qSerre (q ^ 2) 2 a b = 0) :
    let X := a * b - q⁻¹ ^ 2 • (b * a)
