private lemma commutator_qcomm_left (a b c : B) (t : k) (h : Commute b c) :
    (a * b - t • (b * a)) * c - c * (a * b - t • (b * a)) =
      (a * c - c * a) * b - t • (b * (a * c - c * a))

private lemma commutator_qcomm_right (a b d : B) (t : k) (h : Commute a d) :
    (a * b - t • (b * a)) * d - d * (a * b - t • (b * a)) =
      a * (b * d - d * b) - t • ((b * d - d * b) * a)

private lemma reverse_two_positive (a b : B) (q : k) (hq : q ≠ 0)
    (hs : qSerre q 3 a b = 0) (ht : qSerre (q ^ 2) 2 b a = 0) :
    let X := a ^ 2 * b - ((q + q⁻¹) * q⁻¹) • (a * b * a) +
      q⁻¹ ^ 2 • (b * a ^ 2)
    let Y := a * b - q⁻¹ ^ 2 • (b * a)
    Y * X - q⁻¹ ^ 2 • (X * Y) = 0

